"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$ErrorActionPreference='"'Continue'
"'$tmp = New-Item -ItemType Directory -Path $env:TEMP'"\\wave3check -Force
# extract new-file content from patches and compare
"'$maps = @(
  @{p='"'data/reports/convergence-wave3-patches/config__managed_files_v2.txt.patch'; f='config/managed_files_v2.txt'},
  @{p='data/reports/convergence-wave3-patches/install_v2.sh.patch'; f='install_v2.sh'},
  @{p='data/reports/convergence-wave3-patches/tests__orchestration_v2__test_install_v2.py.patch'; f='tests/orchestration_v2/test_install_v2.py'}
)
foreach ("'$m in $maps) {
  $lines = Get-Content $m.p
  $body = @()
  $inHunk = $false
  foreach ($l in $lines) {
    if ($l.StartsWith('"'@@')) { "'$inHunk = $true; continue }
    if ($inHunk -and $l.StartsWith('"'+')) { "'$body += $l.Substring(1) }
  }
  $out = Join-Path $tmp ([IO.Path]::GetFileName($m.f) + '"'.frompatch')
  [IO.File]::WriteAllLines("'$out, $body)
  $cur = Get-Content $m.f -Raw
  $pat = (Get-Content $out -Raw)
  # normalize line endings
  $curN = $cur -replace "`r`n","`n"
  $patN = $pat -replace "`r`n","`n"
  Write-Output ($m.f + '"' MATCH=' + ("'$curN.TrimEnd() -eq $patN.TrimEnd()))
}'

