"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$maps = @(
  @{p='"'data/reports/convergence-wave3-patches/config__managed_files_v2.txt.patch'; f='config/managed_files_v2.txt'},
  @{p='data/reports/convergence-wave3-patches/install_v2.sh.patch'; f='install_v2.sh'},
  @{p='data/reports/convergence-wave3-patches/tests__orchestration_v2__test_install_v2.py.patch'; f='tests/orchestration_v2/test_install_v2.py'}
)
foreach ("'$m in $maps) {
  $lines = Get-Content $m.p
  $body = @()
  $inHunk = $false
  foreach ($l in $lines) {
    if ($l.StartsWith('"'@@')) { "'$inHunk = $true; continue }
    if ($inHunk -and $l.StartsWith('"'+')) { "'$body += $l.Substring(1) }
  }
  $cur = (Get-Content $m.f)
  $diffFound = $false
  $n = [Math]::Max($cur.Count, $body.Count)
  for ($i=0; $i -lt $n; $i++) {
    if ($cur[$i] -cne $body[$i]) {
      if (-not $diffFound) { Write-Output ($m.f + '"' DIFFERS; first diffs:') ; "'$diffFound = $true }
      Write-Output ('"'  L' + ("'$i+1) + '"' CUR=[' + "'$cur[$i] + '"'] PATCH=[' + "'$body[$i] + '"']')
      if ("'$i -gt 2000) { break }
    }
  }
  if (-not $diffFound) { Write-Output ($m.f + '"' IDENTICAL lines=' + "'$cur.Count) }
}
Write-Output '"'--- snapshot vs monitor ---'
"'$sn = Get-Content data/reports/convergence-wave3-patches/loop_monitor_server.py.snapshot
$cu = Get-Content harness/loop_monitor_server.py
Write-Output ('"'snapshot lines=' + "'$sn.Count + '"' current lines=' + "'$cu.Count)
$max = [Math]::Max($sn.Count,$cu.Count); $c=0
for ($i=0;$i -lt $max;$i++){ if ($sn[$i] -cne $cu[$i]) { $c++; if ($c -le 20){ Write-Output ('"'  L'+("'$i+1)+'"' CUR=['+"'$cu[$i]+'"'] SNAP=['+"'$sn[$i]+'"']') } } }
Write-Output ('total differing lines=' + "'$c)'

